// ignore_for_file: depend_on_referenced_packages, deprecated_member_use

/// Envied package lint rules.
///
/// Ensures compile-time secrets generated by Envied are obfuscated so that API
/// keys and tokens are not stored as plain-text string constants in the binary.
library;

import 'package:analyzer/dart/ast/ast.dart';

import '../../saropa_lint_rule.dart';

/// Warns when Envied annotation lacks obfuscate parameter.
///
/// Since: v2.2.0 | Updated: v17.10.0 | Rule version: v3
///
/// Alias: envied_obfuscate, require_env_obfuscation
///
/// Environment variables generated by Envied should be obfuscated to prevent
/// easy extraction from compiled binaries.
///
/// `bool` fields are exempt: a two-value flag cannot carry a secret, and
/// obfuscating it turns the generated `static const` into a runtime-computed
/// `static final`, losing compile-time constness. Every other type (including
/// `int`, which can hold a PIN or numeric ID) is still reported.
///
/// **BAD:**
/// ```dart
/// @Envied()
/// abstract class Env {
///   @EnviedField()
///   static const String apiKey = _Env.apiKey;
/// }
/// ```
///
/// **GOOD:**
/// ```dart
/// @Envied(obfuscate: true)
/// abstract class Env {
///   @EnviedField(obfuscate: true)
///   static const String apiKey = _Env.apiKey;
/// }
/// ```
class RequireEnviedObfuscationRule extends SaropaLintRule {
  RequireEnviedObfuscationRule() : super(code: _code);

  @override
  LintImpact get impact => LintImpact.warning;

  @override
  RuleType? get ruleType => RuleType.codeSmell;

  @override
  Set<String> get tags => const {'packages'};

  @override
  RuleCost get cost => RuleCost.medium;

  static const LintCode _code = LintCode(
    'require_envied_obfuscation',
    '[require_envied_obfuscation] Envied environment variable generated without obfuscation stores secrets as plain text string constants in the compiled binary. Attackers can extract API keys, database URLs, and authentication tokens using basic reverse engineering tools, enabling unauthorized access to your backend services and third-party APIs. {v3}',
    correctionMessage:
        'Add obfuscate: true to the @Envied annotation or individual @EnviedField annotations to encode secrets at compile time and prevent plain text extraction.',
    severity: DiagnosticSeverity.WARNING,
  );

  @override
  void runWithReporter(
    SaropaDiagnosticReporter reporter,
    SaropaContext context,
  ) {
    context.addAnnotation((Annotation node) {
      final String name = node.name.name;
      if (name != 'Envied' && name != 'EnviedField') return;

      // For class-level @Envied, skip if all @EnviedField annotations
      // in the class already specify obfuscate explicitly.
      if (name == 'Envied') {
        final AstNode classNode = node.parent;
        if (classNode is ClassDeclaration &&
            _allFieldsHandleObfuscation(classNode)) {
          return;
        }
      }

      // A bool field has nothing to protect, whatever the annotation says.
      final AstNode annotated = node.parent;
      if (name == 'EnviedField' &&
          annotated is FieldDeclaration &&
          _isBoolField(annotated)) {
        return;
      }

      // Check for obfuscate: true
      final ArgumentList? args = node.arguments;
      if (args == null) {
        reporter.atNode(node);
        return;
      }

      final bool hasObfuscate = args.arguments.any((Argument arg) {
        if (arg is NamedArgument) {
          if (arg.name.lexeme == 'obfuscate') {
            return arg.argumentExpression.toSource() == 'true';
          }
        }
        return false;
      });

      if (!hasObfuscate) {
        reporter.atNode(node);
      }
    });
  }

  /// Returns true if every variable in [field] is a `bool` or `bool?`.
  static bool _isBoolField(FieldDeclaration field) {
    final TypeAnnotation? declared = field.fields.type;

    return field.fields.variables.every((VariableDeclaration variable) {
      final type = variable.declaredFragment?.element.type;
      if (type != null) return type.isDartCoreBool;

      // Syntactic scan (no element model): only an explicit, unprefixed
      // `bool` annotation proves the type; an inferred type stays reported.
      return declared is NamedType &&
          declared.importPrefix == null &&
          declared.name.lexeme == 'bool';
    });
  }

  /// Returns true if every @EnviedField in the class either explicitly
  /// specifies an `obfuscate` argument (true or false) or is a `bool` field.
  static bool _allFieldsHandleObfuscation(ClassDeclaration classDecl) {
    bool hasAnyField = false;

    for (final ClassMember member in classDecl.bodyMembers) {
      if (member is! FieldDeclaration) continue;

      for (final Annotation annotation in member.metadata) {
        if (annotation.name.name != 'EnviedField') continue;
        hasAnyField = true;

        // Bool flags need no decision, so they must not keep the class-level
        // @Envied diagnostic alive.
        if (_isBoolField(member)) continue;

        final ArgumentList? args = annotation.arguments;
        if (args == null) return false;

        final bool specifiesObfuscate = args.arguments.any((Argument arg) {
          if (arg is NamedArgument) {
            return arg.name.lexeme == 'obfuscate';
          }
          return false;
        });

        if (!specifiesObfuscate) return false;
      }
    }

    return hasAnyField;
  }
}
